contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function containing all test logic
    // params: caller address tries to withdraw, and amount to send to contract beforehand
    function runTest(address payable caller, uint fundAmount) public payable {
        // fund this test contract so it can forward funds to c
        require(msg.value == 0, "do not send Ether to this function");
        // ensure this contract has enough balance to fund c if requested
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");

        // send Ether to c so it has a balance (call fallback by sending plain value)
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok, "funding failed");

        // record c balance before attempted withdraw
        uint balBefore = address(c).balance;

        // Attempt withdrawAll from caller: we simulate by using .call to invoke withdrawAll as caller
        // Construct calldata for withdrawAll(): its signature is withdrawAll()
        bytes memory payload = abi.encodeWithSignature("withdrawAll()");
        (bool success, ) = address(c).call{from: caller}(payload);

        // After the call, observe c's balance
        uint balAfter = address(c).balance;

        // The general rule: only the owner can cause the contract's balance to decrease by withdrawAll,
        // so if the caller is not the owner, the balance must remain the same; conversely, if caller is owner, balance can decrease.
        // We express a machine-checkable condition: if the caller is equal to c.owner(), then balAfter <= balBefore, otherwise balAfter == balBefore.
        // (Using <= for owner accounts to allow zero-change if owner withdraws zero.)
        address owner = c.owner();
        if (caller == owner) {
            assert(balAfter <= balBefore);
        } else {
            assert(balAfter == balBefore);
        }
    }

    // allow this test contract to receive Ether for funding c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller supplies no params; we only observe whether withdrawAll reverts for msg.sender
    function run() public payable {
        // No precondition required: we state a general rule about caller identity.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // General rule: withdrawAll must revert when called by someone who is not the owner.
        // Since this test is executed by the transaction sender, we express that it must revert
        // unless msg.sender equals the owner — but we cannot call owner() because owner() is public.
        // Use the public getter to compare: if this caller is not the owner, then reverted must be true.
        // If this caller is the owner, reverted may be false. So assert: (msg.sender == c.owner()) || reverted
        assert(msg.sender == c.owner() || reverted);
    }
}

