import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: amount to send and an arbitrary bytes payload
    function testFuzz_property(uint128 amount, bytes memory data) public {
        // keep amount within reasonable bounds but wide
        uint256 amt = uint256(amount);
        // fund the contract so sendMoney can forward value without reverting for lack of balance
        // the submitter (owner) is the test contract deployer, which is address(this) because new C() in setUp
        vm.deal(address(this), amt + 1);

        // ensure the contract has some balance to forward
        // send some ether into c so sendMoney can move it out
        (bool sent,) = address(c).call{value: amt}("");
        require(sent);

        // record balance before owner calls sendMoney
        uint256 before = address(c).balance;

        // owner is the deployer (this contract). Call sendMoney as owner (no prank needed)
        // route the target to address payable(this) so funds would return to this contract if forwarded
        // call with value 0 (we are testing that owner is allowed to call the function to move existing funds)
        // Use try/catch to avoid bubbling reverts; we want to observe resulting balance
        try c.sendMoney(address(this), amt, data) {
            // no-op
        } catch {
            // ignored; we will check balance regardless
        }

        uint256 after = address(c).balance;

        // The reference property: when the owner (deployer) calls sendMoney, the call is permitted
        // and may change the contract balance; specifically, since we targeted the contract's balance
        // to be forwarded to this contract, the reference will allow the owner to perform the call.
        // We assert that either the balance decreased (owner was allowed to move funds out) OR the call reverted.
        // For the correct contract the owner is allowed, so after <= before must hold (balance cannot increase due
        // to this outgoing transfer), and specifically after < before for some fuzzed inputs (the mutant blocks owner).
        // To make this a single boolean property that the correct contract always satisfies but the mutant
        // can violate for some inputs, we assert that after <= before.
        assertTrue(after <= before);
    }
}

