        // fund the contract so there's balance to move
        vm.deal(address(this), 1 ether);
        // send some ETH into c so sendMoney can forward it
        c.sendMoney{value: 1 ether}(address(this), 0, "");

        // The deciding actor is the owner (deployer of c), which is address(this) because setUp used new C()
        // Owner should be able to call sendMoney on the reference contract and thus may change address(c).balance.
        // We fuzz calldata 'data' though it doesn't affect onlyOwner check; it still exercises sendMoney.

        // record balance before
        uint256 beforeBal = address(c).balance;

        // act as owner and call sendMoney forwarding amt
        vm.prank(address(this));
        // ensure caller has funds to forward if needed (sendMoney forwards from contract's balance, so no extra funds required)
        // call sendMoney with fuzzed bytes and fuzzed amount
        // we catch any revert to observe behavior through c's external surface
        bool ok;
        try c.sendMoney(address(this), amt, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property we assert: after the owner calls sendMoney, either the call reverted (ok==false)
        // or the contract's balance changed (ok==true implies balance may decrease or remain depending on callee),
        // but for the correct contract the owner is allowed so if it succeeds the balance should be <= beforeBal.
        // We express a universal property that the owner is allowed to invoke owner-only behaviour: if the call succeeded,
        // the contract balance is not increased by the call.

        // Single assertion observing c: if call succeeded then balance <= beforeBal
        assertTrue(!ok || address(c).balance <= beforeBal);
    }
}

