        deposit = bound(deposit, 1, type(uint256).max);

        // fund the owner EOA so it can send deposit and receive withdraw
        vm.deal(owner, deposit + 1 ether);

        // owner becomes the deployer in constructor? In setUp we deployed c as this test contract,
        // so to simulate owner semantics we must deploy a fresh contract where owner is owner address.
        // The instruction mandated to deploy c in setUp() with `new C()` verbatim; owner is therefore address(this).
        // To exercise withdrawAll via the public owner, we will instead interact as the deployer (address(this)).
        // So we must send ETH into c from the owner (we can use any address). Use vm.prank to send deposit from owner.

        // Send deposit into contract by calling fallback (simple plain transfer)
        vm.prank(owner);
        (bool sent,) = address(c).call{value: deposit}("\x00");
        require(sent, "funding failed");

        // Record contract balance before withdrawAll
        uint256 before = address(c).balance;

        // call withdrawAll as the owner (the contract c was deployed by this test contract in setUp,
        // so msg.sender==owner in contract is address(this)). We must call as address(this) which is default.
        // Ensure the test contract has enough balance to receive funds (it does)
        // Call withdrawAll and allow it to execute
        try c.withdrawAll() {
            // success
        } catch {
            // If withdrawAll reverts for some inputs, treat as failure of property; but reference should not revert
        }

        // After withdrawAll, the correct contract should have balance 0. The mutant that subtracts 1 wei
        // will leave 1 wei when before > 0. We assert the universal property: address(c).balance == 0
        assertTrue(address(c).balance == 0);
    }
}

