    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint value, bytes calldata data) public payable {
        // Restrict inputs so that the caller is not the contract owner stored in c
        // and the call is made with zero value to avoid transferring ETH from this test
        // Also require that the test caller is not equal to the stored c.owner() address
        // and ensure the target is not the C contract itself (avoids calling into c via target)
        // Additionally ensure that the provided target is not equal to address(0)
        require(target != address(0) && value == 0 && msg.sender != c.owner() && msg.sender != address(c) && target != address(c));
        // No extra precondition: we want to test calls from a non-owner (msg.sender here)
        // Ensure we don't rely on sending ETH from this test; call without value
        bool reverted;
        try c.sendMoney(target, value, data) { reverted = false; } catch { reverted = true; }
        // In the original contract only the owner can call sendMoney, so any caller
        // that is not the owner must observe a revert. We express that generally
        // in terms of the revert flag (and do not refer to c's internals).
        assert(reverted == true);
    }
    receive() external payable { }
}

