pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: attacker address (will be non-owner) and amount to send from contract to target
    function testFuzz_property(address attacker, uint256 sendAmt) public {
        // keep attacker distinct from the owner (deployer)
        vm.assume(attacker != address(this));

        // bound the send amount to a reasonable range (allow zero too)
        sendAmt = bound(sendAmt, 0, 1 ether);

        // Fund the contract with some ETH so there is something to send
        vm.deal(address(this), 2 ether);
        // send funds into c from this contract (deployer/owner)
        payable(address(c)).transfer(1 ether);
        uint256 before = address(c).balance;
        // sanity: before should be >= sendAmt in many cases, but we allow any

        // Deploy a helper that will accept Ether (acts like a payable recipient)
        AttackerReceiver recv = new AttackerReceiver();

        // Ensure attacker caller is used (non-owner). Give attacker some funds to pay gas if needed.
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        // Call sendMoney through attacker to recipient; sendAmt passed as value to be forwarded from contract
        // Note: sendMoney is non-payable for caller, but it makes the contract call _target.call{value: _value}(_data);
        // We provide empty data.
        try c.sendMoney(address(recv), sendAmt, "") {
            // call returned normally
        } catch {
            // ignore revert: reference contract will revert if not owner? In reference it has onlyOwner so non-owner cannot call and will revert.
            // But we continue to observe contract balance regardless
        }

        uint256 after = address(c).balance;

        // General rule: In the correct contract, non-owner callers cannot change contract balance via sendMoney,
        // therefore for ANY attacker address (not owner) and ANY sendAmt, after == before.
        // The mutant removes onlyOwner, so for some inputs (sendAmt>0 and recipient accepts funds) after < before.
        assertTrue(after == before);
    }
}

