pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 amount) public {
        // Keep amount within reasonable bounds and non-zero to allow transfer
        amount = bound(amount, 0, 10 ether);

        // Ensure the contract has some balance to attempt to send
        vm.deal(address(this), 10 ether);
        // fund the contract
        payable(address(c)).transfer(5 ether);
        // sanity: contract now has 5 ether

        // Deploy a helper that accepts Ether so transfers succeed if attempted
        Receiver rec = new Receiver();

        // Attacker is a fuzzed EOA; if non-owner can call sendMoney, they may cause balance to decrease
        // Make attacker have funds to send (not strictly necessary for low-level call, but safe)
        vm.deal(attacker, 1 ether);

        // Have attacker call sendMoney attempting to forward 'amount' to Receiver
        vm.prank(attacker);
        bool ok;
        try c.sendMoney(address(rec), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // PROPERTY: For any attacker and amount, if caller is NOT owner the contract balance must NOT decrease.
        // We observe this by checking that after the call, the contract's balance is at least 5 ether - (owner-only transfers not allowed by reference).
        // Since the reference enforces onlyOwner, any non-owner call must not reduce balance: balance >= 5 ether.
        // Note: if attacker == owner (the deployer), owner may legitimately withdraw; in that case we cannot assert. So we restrict assertion to attacker != owner.
        if (attacker != address(this)) {
            assertTrue(address(c).balance >= 5 ether);
        }
    }
}

// Minimal receiver that accepts Ether
contract Receiver {
    receive() external payable {}
}
